-- Minimal pre-migration tables, matching the columns used from shared/schema.ts.
CREATE TABLE users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,role TEXT NOT NULL,stripe_account_id TEXT);
CREATE TABLE projects(id SERIAL PRIMARY KEY,client_id INTEGER NOT NULL,freelancer_id INTEGER NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active',current_stage INTEGER NOT NULL DEFAULT 0,freelancer_name TEXT,client_name TEXT,is_retainer INTEGER DEFAULT 0,billing_cycle TEXT,total_cycles INTEGER,created_at TEXT NOT NULL);
CREATE TABLE retainer_cycles(id SERIAL PRIMARY KEY,project_id INTEGER NOT NULL,cycle_number INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',start_date TEXT NOT NULL,end_date TEXT,freelancer_note TEXT,payment_status TEXT NOT NULL DEFAULT 'unpaid',created_at TEXT NOT NULL);
CREATE TABLE invoices(id SERIAL PRIMARY KEY,invoice_number TEXT NOT NULL,project_id INTEGER NOT NULL,freelancer_id INTEGER NOT NULL,client_id INTEGER NOT NULL,client_name TEXT NOT NULL DEFAULT '',client_email TEXT NOT NULL DEFAULT '',project_title TEXT NOT NULL DEFAULT '',line_items TEXT NOT NULL DEFAULT '[]',subtotal_pence INTEGER NOT NULL DEFAULT 0,vat_pence INTEGER NOT NULL DEFAULT 0,total_pence INTEGER NOT NULL DEFAULT 0,notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'sent',issued_at TEXT NOT NULL,paid_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE upload_objects(id SERIAL PRIMARY KEY);
CREATE TABLE notifications(id SERIAL PRIMARY KEY,recipient_id INTEGER NOT NULL,actor_id INTEGER NOT NULL,actor_name TEXT NOT NULL,type TEXT NOT NULL,message TEXT NOT NULL,link TEXT);
